{"code": "async (page) => {
    // Extract the full article text
    const articleContent = await page.evaluate(() => {
        const article = document.querySelector('article');
        if (!article) return null;

        // Remove navigation and other non-content elements
        const clone = article.cloneNode(true);
        const toRemove = clone.querySelectorAll('nav, .navigation, .post-navigation, .banner, header');
        toRemove.forEach(el => el.remove());

        // Get all paragraphs and headings
        const elements = clone.querySelectorAll('p, h1, h2, h3, h4, h5, h6');
        let text = '';
        elements.forEach(el => {
            // Skip empty elements
            if (el.textContent.trim()) {
                // Add appropriate formatting
                const tagName = el.tagName.toLowerCase();
                if (tagName.startsWith('h')) {
                    const level = parseInt(tagName.charAt(1));
                    const prefix = '#'.repeat(level) + ' ';
                    text += prefix + el.textContent.trim() + '\n\n';
                } else {
                    text += el.textContent.trim() + '\n\n';
                }
            }
        });
        return text;
    });
    return articleContent;
}"}

