{"code": "async (page) => {
    // Check for publication date metadata
    const dateInfo = await page.evaluate(() => {
        // Look for any date information on the page
        const metaDate = document.querySelector('meta[property="article:published_time"], meta[name="date"], meta[name="publication_date"]');
        const dateText = document.body.innerText.match(/(June|July|August|September|October|November|December|January|February|March|April|May)\s+\d{4}/i);
        const yearText = document.body.innerText.match(/2014/i);

        return {
            metaDate: metaDate ? metaDate.getAttribute('content') : null,
            dateMatch: dateText ? dateText[0] : null,
            yearMatch: yearText ? yearText[0] : null,
            url: window.location.href
        };
    });
    return dateInfo;
}"}

